values
  ('316ede18-818f-4783-aa2b-069a6b3fdc1c', 'd8843252-fe2f-4af3-8999-94c2b8ec69b6', '김지은', 5, '얼굴형에 맞게 잘라주셔서 이전보다 훨씬 자연스러워요. 상담도 꼼꼼하게 해주셨어요.'),
