  ('42df9d9b-b20f-44d9-8f0f-81dc9ecf08bc', 'd8843252-fe2f-4af3-8999-94c2b8ec69b6', '윤소희', 5, '볼륨이 자연스럽게 살아서 만족해요. 웨이브도 예쁘게 나왔습니다.'),
