  ('1b67e8c1-0309-4332-87a2-9102ad682e8e', 'fee6a268-f6bf-425e-80b6-dbd16ed30abe', '배성민', 5, '그러데이션이 정말 자연스럽게 나왔어요. 주변에서 다들 물어봐요.'),
